function getToastData(templates) {
    const data = {};
    return templates.reduce((pv, cv) => {
        switch (cv.type()) {
            case 'header':
                pv.header = cv.templateRef;
                return pv;
            case 'icon':
                pv.icon = cv.templateRef;
                return pv;
            case 'description':
                pv.description = cv.templateRef;
                return pv;
            case 'footer':
                pv.footer = cv.templateRef;
                return pv;
        }
    }, data);
}

